<script>const pack=document.getElementById('package-type'),fls=document.getElementById('fls-product'),camera=document.getElementById('camera-product');function sync(){const f=pack.value!=='Basic',c=pack.value==='Basic + FLS + Camera';fls.required=f;camera.required=c;fls.disabled=!f;camera.disabled=!c;}pack.addEventListener('change',sync);sync();</script>
